1	export type Cell = [x: number, y: number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const toKey = ([x, y]: Cell): string => `${x},${y}`;
10	const fromKey = (key: string): Cell => {
11	  const [x, y] = key.split(",").map(Number);
12	  return [x, y];
13	};
14	
15	export function nextGeneration(livingCells: Cell[]): Cell[] {
16	  const alive = new Set(livingCells.map(toKey));
17	  const neighborCounts = countNeighbors(livingCells);
18	
19	  const survives = (key: string, count: number) =>
20	    (count === 3) || (count === 2 && alive.has(key));
21	
22	  return [...neighborCounts]
23	    .filter(([key, count]) => survives(key, count))
24	    .map(([key]) => fromKey(key));
25	}
26	
27	function countNeighbors(livingCells: Cell[]): Map<string, number> {
28	  const counts = new Map<string, number>();
29	  for (const [x, y] of livingCells) {
30	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
31	      const key = toKey([x + dx, y + dy]);
32	      counts.set(key, (counts.get(key) ?? 0) + 1);
33	    }
34	  }
35	  return counts;
36	}
