export function nextGeneration(livingCells: Cell[]): Cell[] {
  const alive = new Set(livingCells.map(toKey));
  const neighborCounts = countNeighbors(livingCells);

  const isAliveNextTick = (key: string, count: number) =>
    count === 3 || (count === 2 && alive.has(key));

  return [...neighborCounts]
    .filter(([key, count]) => isAliveNextTick(key, count))
